<?php
namespace App\Livewire\BulkImport;
use App\Domain\Audit\Services\AuditRecorder;use App\Domain\BulkImport\Enums\MigrationBatchStatus;use App\Jobs\CommitMigrationBatch;use App\Models\MigrationBatch;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;
#[Layout('layouts.app')]
class MigrationBatchView extends Component{use WithPagination;public MigrationBatch $batch;public string $filter='';public function mount(MigrationBatch $batch):void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'bulk.import'),403);$this->batch=$batch;}public function approve(AuditRecorder $audit):void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'bulk.manage'),403);abort_if($this->batch->failed_items>0,409,'Fix validation errors before approval.');$this->batch->update(['approved_by'=>auth()->id(),'approved_at'=>now(),'status'=>MigrationBatchStatus::AwaitingApproval]);$audit->record('MIGRATION_BATCH_APPROVED','BULK_IMPORT','SUCCESS',auth()->user(),['subject_type'=>'migration_batch','subject_ulid'=>$this->batch->ulid,'context'=>['batch_reference'=>$this->batch->batch_reference,'items'=>$this->batch->total_items]]);CommitMigrationBatch::dispatch($this->batch->id);$this->batch->refresh();}public function retryValidation():void{\App\Jobs\ValidateMigrationBatch::dispatch($this->batch->id);session()->flash('success','Validation queued.');}public function render(){return view('livewire.bulk-import.migration-batch-view',['items'=>$this->batch->items()->when($this->filter,fn($q)=>$q->where('status',$this->filter))->orderBy('source_row_number')->paginate(50)]);}}
